#include "Studio.h"
#include <cmath>
namespace pulse {
using namespace juce;
void Studio::runChorusChecks(const File& folder,const std::function<void(bool,const String&)>& check){
    cancelNoteTool();closeCommandPalette();project=emptyProject();project.bpm=120;project.loop=false;currentFile=File();selectedTrack=7;selectedNotes.clear();selectedNote=-1;undoStack.clear();redoStack.clear();project.patterns[0].length=4;lane()={{0,1,60,.8f}};publish();perform(stop);resetLayout();setSize(1180,800);showPane(mixerPane);
    auto draw=[&]{hits.clear();Image image(Image::RGB,getWidth(),getHeight(),true);Graphics g(image);paint(g);};
    auto event=[&](Point<float> p,int mods=ModifierKeys::leftButtonModifier){auto time=Time::getCurrentTime();return MouseEvent(Desktop::getInstance().getMainMouseSource(),p,ModifierKeys(mods),1,0,0,0,0,this,this,time,p,time,1,false);};
    draw();auto slot=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.pane==mixerPane&&h.action==effectsOpen&&h.data==3;});check(slot!=hits.end(),"Mixer exposes a real fourth stereo chorus effect slot");if(slot!=hits.end()){auto click=event(slot->rect.getCentre());mouseDown(click);mouseUp(click);}check(activePane==effectsPane&&selectedEffect==3,"clicking chorus slot opens the existing effects window on Chorus");
    auto original=JSON::toString(projectToJson(project));perform(effectToggle,3);check(project.tracks[7].mixer.chorus.enabled&&undoStack.size()==1,"chorus enable is a single project edit");perform(undoAction);check(JSON::toString(projectToJson(project))==original,"chorus bypass Undo restores full project including pattern length");perform(redoAction);check(project.tracks[7].mixer.chorus.enabled,"chorus enable Redo restores effect");
    draw();std::set<int> knobs;bool fits=true;for(const auto& hit:hits)if(hit.pane==effectsPane){fits&=workspaceBounds().contains(hit.rect);if(hit.action>=chorusMix&&hit.action<=chorusWidth)knobs.insert(hit.action);}check(fits&&knobs.size()==6,"six chorus controls and four tabs fit compact effect window");snapshot(folder.getChildFile("stereo-chorus.png"));
    undoStack.clear();auto before=project.tracks[7].mixer.chorus;auto knob=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.action==chorusRate;});
    if(knob!=hits.end()){auto point=knob->rect.getCentre();mouseDown(event(point));mouseDrag(event(point+Point<float>(0,-35)));mouseUp(event(point));}
    check(project.tracks[7].mixer.chorus.rate>before.rate&&undoStack.size()==1,"chorus rate mouse drag changes the logarithmic control in one undo");perform(undoAction);check(project.tracks[7].mixer.chorus==before,"chorus drag Undo restores exact complete effect settings");
    draw();knob=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.action==chorusFeedback;});MouseWheelDetails wheel;wheel.deltaY=.12f;if(knob!=hits.end())mouseWheelMove(event(knob->rect.getCentre()),wheel);check(project.tracks[7].mixer.chorus.feedback>before.feedback,"mouse wheel edits signed chorus feedback");perform(undoAction);
    checkpoint();setParameter(chorusDelay,7,1);draw();knob=std::find_if(hits.begin(),hits.end(),[](const Hit& h){return h.action==chorusDelay;});if(knob!=hits.end()){auto click=event(knob->rect.getCentre(),ModifierKeys::leftButtonModifier|ModifierKeys::altModifier);mouseDown(click);mouseUp(click);}check(std::abs(project.tracks[7].mixer.chorus.delay-15)<.00001,"Alt-click resets a chorus knob to its musical default");perform(undoAction);check(project.tracks[7].mixer.chorus.delay==35,"chorus reset is undoable");
    auto entries=paletteEntries();int commands=0;for(auto i:searchCommands(entries,"channel chorus"))if(entries[(size_t)i].data==3&&(entries[(size_t)i].action==effectsOpen||entries[(size_t)i].action==effectToggle))++commands;check(commands==2,"Ctrl+P finds chorus open and bypass commands");
    auto file=folder.getChildFile("ui-chorus.pulse");Project reopened;check(saveProject(project,file).wasOk()&&loadProject(file,reopened).wasOk()&&reopened.tracks[7].mixer.chorus==project.tracks[7].mixer.chorus&&reopened.patterns[0].length==4,"editor save/reopen retains chorus and variable Channel rack steps");
    auto frozen=JSON::toString(projectToJson(project));recording=true;perform(effectToggle,3);setParameter(chorusMix,7,.9f);check(JSON::toString(projectToJson(project))==frozen,"recording guards chorus bypass and parameter mutation");recording=false;setParameter(chorusMix,7,std::numeric_limits<float>::quiet_NaN());check(JSON::toString(projectToJson(project))==frozen,"nonfinite chorus editor input cannot change the project");
    checkpoint();setParameter(chorusMix,7,.65f);setParameter(chorusDepth,7,.75f);setParameter(chorusWidth,7,1);showPane(effectsPane);perform(play);AudioBuffer<float> output(2,512);float peak=0;for(int i=0;i<80;++i){getNextAudioBlock(AudioSourceChannelInfo(&output,0,512));peak=jmax(peak,output.getMagnitude(0,0,512));}check(peak>.001f&&engine->playing.load(),"chorus effect produces audible callback audio from the current pattern");perform(stop);getNextAudioBlock(AudioSourceChannelInfo(&output,0,512));check(output.getMagnitude(0,0,512)==0,"editor Stop clears all chorus feedback");
    project.tracks[5].isBus=true;project.tracks[5].name="Chorus bus";selectedTrack=5;perform(effectsOpen,3);perform(effectToggle,3);check(project.tracks[5].mixer.chorus.enabled&&selectedEffect==3,"bus inserts expose the same usable chorus controls");perform(undoAction);selectedTrack=7;showPane(effectsPane);draw();snapshot(folder.getChildFile("stereo-chorus-final.png"));
}
}
